+        let b: Bounds = ([3.0, 0.0, 0.0], [4.0, 1.0, 1.0]);
+        assert!(!near(&a, &b, 0.5));
+        assert!(near(&a, &b, 2.5));
+        let nan: Bounds = ([f64::NAN; 3], [f64::NAN; 3]);
+        assert!(near(&a, &nan, 0.0));
+    }
+}

